   ```

2. Создайте новый файл и назовите его `index.js`.

3. В начале файла, импортируйте необходимые библиотеки:

   ```javascript
   const { Client, GatewayIntentBits } = require('discord.js');
   ```

4. Создайте новый экземпляр клиента Discord:

   ```javascript
   const client = new Client({
     intents: [GatewayIntentBits.Guilds, GatewayIntentBits.GuildMessages],
   });
   ```

   В данном примере мы настроили клиента на получение событий с серверами и сообщениями.

5. Следующим шагом, авторизуйте бота на вашем Discord сервере. Добавьте в `index.js` токен вашего бота:

   ```javascript
   const token = 'YOUR_DISCORD_BOT_TOKEN';
   ```

   Замените `YOUR_DISCORD_BOT_TOKEN` на ваш токен Discord.

6. Создайте функцию для обработки команды бан:

   ```javascript
   const banCommand = async (interaction) => {
     const member = interaction.options.getMember('user');
     if (!member) {
       return interaction.reply({
         content: 'Пожалуйста, упомяните пользователя, которого хотите забанить.',
         ephemeral: true,
       });
     }

     const guild = interaction.guild;
     const memberRole = guild.roles.cache.find((r) => r.name === '@everyone');

     await guild.members.ban(member, {
       reason: `Banned by ${interaction.user.tag}`,
     });

     await interaction.reply({
       content: `${member.user.tag} был забанен на сервере ${guild.name}.`,
     });
   };
   ```

   В этой функции мы получаем пользователя, который был упомянут в команде, и забаниваем его на сервере. Мы также отправляем уведомление о результате операции.

7. Добавьте слэш-команду бан в ваше приложение:

   ```javascript
