Here's a possible implementation of the C++ function that takes a reference to a std::string containing a text in a markdown format and returns a std::string containing the same text in HTML format:

```cpp
#include <iostream>
#include <string>
#include <regex>

// Function to convert markdown to HTML
std::string markdown_to_html(const std::string& markdown) {
    // Define regex patterns for markdown formatting
    static const std::regex heading_pattern(R"(\n#+(\s+.*)?)");
    static const std::regex bold_pattern(R"(\*\*(.+)\*\*)");
    static const std::regex italic_pattern(R"(\*(.+)\*)");
    static const std::regex strikethrough_pattern(R"(\~\~(.+)\~\~)");
    static const std::regex link_pattern(R"( \[(.+)\]\((.+)\))");
    static const std::regex image_pattern(R"( !\[(.+)\]\((.+)\))");

    // Initialize HTML string
    std::string html;

    // Replace headings with HTML tags
    auto heading_match = std::regex_search(markdown, heading_pattern);
    while (heading_match) {
        std::string heading_text = std::regex_replace(std::regex_match(1, heading_pattern), std::regex(R"(\s+)"), "");
        html += "<h" + std::to_string(1 + std::stoi(std::regex_match(0, heading_pattern))) + ">" + heading_text + "</h" + std::to_string(1 + std::stoi(std::regex_match(0, heading_pattern))) + ">\n";
        heading_match = std::regex_search(markdown, heading_pattern);
    }

    // Replace bold, italic, and strikethrough text with HTML tags
    markdown.replace_all(std::regex(bold_pattern), "<strong>$1</strong>");
    markdown.replace_all(std::regex(italic_pattern), "<em>$1</em>");
    markdown.replace_all(std::regex(strikethrough_pattern), "<del>$1</del>");

    // Replace links with HTML tags
    auto link_match = std::regex_search(markdown, link_pattern);
    while (link_match) {
        std::string link_text = std::regex_replace(std::regex_match(1, link_pattern), std::regex(R"(\s+)"), "");
        std::string link_url = std::regex_replace(std::regex_match(2, link_pattern), std::regex(R"(\s+)"), "");
        html += "<a href='" + link_url + "'>" + link_text + "</a>\n";
        link_match = std::regex_search(markdown, link_pattern);
    }

    // Replace images with HTML tags
    auto image_match = std::regex_search(markdown, image_pattern);
    while (image_match) {
        std::string image_alt = std::regex_replace(std::regex_match(1, image_pattern), std::regex(R"(\s+)"), "");
        std::string image_url = std::regex_replace(std::regex_match(2, image_pattern), std::regex(R"(\s+)"), "");
        html += "<img src='" + image_url + "' alt='" + image_alt + "' />\n";
        image_match = std::regex_search(markdown, image_pattern);
    }

    return html;
}

int main() {
    std::string markdown = "Hello **bold** text! This is _italic_ and ~~strikethrough~~. [Link](https://example.com) and ! [Image](https://example.com/image.png)";
    std::string html = markdown_to_html(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

This implementation uses regular expressions to identify the markdown formatting and replace them with corresponding HTML tags. Note that this implementation only covers a subset of markdown syntax, but it should give you an idea of how to implement a more complete solution. You can add more patterns and corresponding HTML tags as needed. Also, make sure to include the necessary headers for regular expressions if your compiler doesn't support them by default.

