#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string word; // слово, которое необходимо искать
    int count = 0; // счетчик вхождений слова

    cout << "Введите слово, которое необходимо искать: ";
    cin >> word;

    string filename;
    cout << "Введите имя файла: ";
    cin >> filename;

    // Открытие файла для чтения
    ifstream file(filename);
    if (!file.is_open()) {
        cout << "Ошибка открытия файла." << endl;
        return 1;
    }

    // Пропуск пустых строк
    string line;
    while (getline(file, line) && line.empty()) {}

    // Поиск слова в файле
    while (getline(file, line)) {
        // Преобразование строки в нижний регистр для чувствительности к регистру
        transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Считаем количество вхождений слова в строке
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) {
            pos++; // Увеличиваем позицию, чтобы не считать повторы
            count++;
        }
    }

    // Вывод результата
    cout << "Количество вхождений слова '" << word << "' в файле '" << filename << "': " << count << endl;

    // Закрытие файла
    file.close();

    return 0;
}
```

Программа просит пользователя ввести слово, которое необходимо искать, а также имя текстового файла. Она открывает файл для чтения, пропускает пустые строки, преобразует каждую строку в нижний регистр для чувствительности к регистру, ищет слово в каждой строке, считает количество вхождений и выводит результат. После завершения работы программа закрывает файл. 

Пожалуйста, убедитесь, что в файле нет символов, которые могут повлиять на работу функции `find()`, например, символы конца строки `\n`. В случае необходимости, можете добавить преобразование строк в нижний регистр в начале каждой строки файла (например, с помощью библиотеки `boost::filesystem`), чтобы учесть различия в регистре символов в исходном файле.
